<script setup lang="ts">
import { onMounted, ref } from "vue";
import { useObjectsStore } from "@/stores/objects";
import { useSensorsStore } from "@/stores/sensors";
import type { ObjectItem, SensorItem } from "@/types";
const objectsStore=useObjectsStore(), sensorsStore=useSensorsStore();
const expanded=ref<string|null>(null), selected=ref<string|null>(null), objectSensors=ref<Record<string,SensorItem[]>>({}), showObject=ref(false), showSensor=ref(false), editing=ref<ObjectItem|null>(null), targetObject=ref("");
const name=ref(""),slug=ref(""),description=ref(""),error=ref("");
async function loadSensors(id:string){await sensorsStore.fetchSensors(id);objectSensors.value[id]=[...sensorsStore.sensors]}
async function toggle(obj:ObjectItem){expanded.value=expanded.value===obj.id?null:obj.id;if(expanded.value)await loadSensors(obj.id)}
function openObject(obj?:ObjectItem){editing.value=obj||null;name.value=obj?.name||"";slug.value=obj?.slug||"";description.value=obj?.description||"";error.value="";showObject.value=true}
async function saveObject(){try{if(editing.value)await objectsStore.updateObject(editing.value.id,{name:name.value,description:description.value});else await objectsStore.createObject({name:name.value,slug:slug.value,description:description.value});showObject.value=false;await objectsStore.fetchObjects()}catch(e){error.value=e instanceof Error?e.message:"Nie udało się zapisać"}}
async function removeObject(){if(!selected.value)return;if(confirm("Usunąć wybrany obiekt?")){await objectsStore.deleteObject(selected.value);selected.value=null}}
function openSensor(id:string){targetObject.value=id;name.value="";slug.value="";error.value="";showSensor.value=true}
async function saveSensor(){try{await sensorsStore.createSensor(targetObject.value,{name:name.value,slug:slug.value});showSensor.value=false;await loadSensors(targetObject.value)}catch(e){error.value=e instanceof Error?e.message:"Nie udało się dodać sensora"}}
async function removeSensor(objectId:string,sensorId:string){if(confirm("Usunąć sensor?")){await sensorsStore.deleteSensor(objectId,sensorId);await loadSensors(objectId)}}
function temp(v:number|null){return v==null?"—":`${v.toFixed(1)} °C`} function date(v:string|null){return v?new Date(v).toLocaleString("pl-PL"):"—"}
onMounted(async()=>{await objectsStore.fetchObjects();if(objectsStore.objects[0]){expanded.value=objectsStore.objects[0].id;await loadSensors(expanded.value)}})
</script>
<template><section class="objects-page"><header class="page-head"><div><h1>Obiekty</h1><p>Zarządzaj swoimi obiektami i sensorami.</p></div><div class="actions"><button class="primary" @click="openObject()">＋　Dodaj obiekt</button><button @click="selected&&openObject(objectsStore.objects.find(x=>x.id===selected))">⌑　 Edytuj obiekt</button><button class="danger" @click="removeObject">♜　 Usuń obiekt</button></div></header><div class="object-list"><article v-for="object in objectsStore.objects" :key="object.id" class="object-panel" :class="{open:expanded===object.id}"><header class="object-row"><input type="checkbox" :checked="selected===object.id" @change="selected=selected===object.id?null:object.id"><button class="object-toggle" @click="toggle(object)"><svg viewBox="0 0 24 24"><path d="M4 21V4h16v17M8 8h2m4 0h2M8 12h2m4 0h2M8 16h2m4 0h2"/></svg><span><b>{{object.name}}</b><small v-if="expanded===object.id">{{(objectSensors[object.id]||[]).length}} sensory</small></span></button><em>{{object.is_active?"Online":"Offline"}}</em><div v-if="expanded===object.id" class="sensor-actions"><button @click="openSensor(object.id)">＋　Dodaj sensor</button><button class="remove" :disabled="!(objectSensors[object.id]||[]).length" @click="removeSensor(object.id,(objectSensors[object.id]||[])[0]?.id)">♜　 Usuń sensor</button></div><button class="chevron" @click="toggle(object)">{{expanded===object.id?"⌃":"›"}}</button></header><div v-if="expanded===object.id" class="sensor-table"><div class="sensor-head"><span>NAZWA SENSORĄ</span><span>AKTUALNA WARTOŚĆ</span><span>OSTATNIA AKTUALIZACJA</span></div><div v-for="sensor in objectSensors[object.id]||[]" :key="sensor.id" class="sensor-row"><span><svg viewBox="0 0 24 24"><path d="M14 14.5V5a2 2 0 0 0-4 0v9.5a5 5 0 1 0 4 0Z"/><path d="M12 11v6"/></svg>{{sensor.name}}</span><strong>{{temp(sensor.current_temperature)}}</strong><time>{{date(sensor.last_message_at)}}</time></div><div v-if="!(objectSensors[object.id]||[]).length" class="no-sensors">Brak sensorów</div></div></article></div><p class="count">Wyświetlanie 1–{{objectsStore.objects.length}} z {{objectsStore.objects.length}} obiektów</p><div v-if="showObject||showSensor" class="modal" @click.self="showObject=false;showSensor=false"><form @submit.prevent="showObject?saveObject():saveSensor()"><h2>{{showObject?(editing?"Edytuj obiekt":"Dodaj obiekt"):"Dodaj sensor"}}</h2><label>Nazwa<input v-model="name" required></label><label>Slug<input v-model="slug" :disabled="!!editing" required pattern="^[a-z0-9]+(-[a-z0-9]+)*$"></label><label v-if="showObject">Opis<textarea v-model="description"></textarea></label><p v-if="error">{{error}}</p><footer><button type="button" @click="showObject=false;showSensor=false">Anuluj</button><button class="primary">Zapisz</button></footer></form></div></section></template>
<style scoped>
.objects-page{padding:20px 31px;max-width:1680px;margin:auto}.page-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.page-head h1{font-size:31px;margin:0 0 4px}.page-head p{margin:0;color:#afbfda;font-size:17px}.actions{display:flex;gap:30px}.actions button,.sensor-actions button{height:57px;min-width:224px;background:#061424;border:1px solid #2a4d6d;border-radius:7px;color:#f1f5ff;font-size:17px}.actions .primary,.primary{background:linear-gradient(115deg,#06c7f3,#078de4);border-color:#139de5}.actions .danger,.sensor-actions .remove{background:linear-gradient(110deg,#ec173d,#be0922);border-color:#ee2944}.object-list{display:flex;flex-direction:column;gap:7px}.object-panel{background:linear-gradient(105deg,#0b1e2d,#0a1928);border:1px solid #162e43;border-radius:7px}.object-row{height:68px;display:flex;align-items:center;padding:0 22px;gap:20px}.object-row input{width:21px;height:21px;accent-color:#06d8e4}.object-toggle{border:0;background:transparent;color:#ecf3ff;display:flex;align-items:center;gap:24px;text-align:left;min-width:215px;cursor:pointer}.object-toggle svg{width:42px;height:42px;color:#00dde1;fill:none;stroke:currentColor;stroke-width:1.4}.object-toggle b{display:block;font-size:19px}.object-toggle small{display:block;color:#b3c3dd;font-size:16px;margin-top:4px}.object-row em{font-style:normal;color:#00dff1;background:#063049;border:1px solid #084363;border-radius:7px;padding:7px 11px}.sensor-actions{display:flex;gap:11px}.sensor-actions button{height:42px;min-width:156px;color:#00d9ed;font-size:15px;background:#062235;border-color:#00aee2}.sensor-actions .remove{color:#ff3151;border-color:#e31337;background:#210d19}.sensor-actions button:disabled{opacity:.35}.chevron{margin-left:auto;background:transparent;border:0;color:#a8c6f2;font-size:35px;cursor:pointer}.sensor-table{margin:17px 14px 8px;border:1px solid #173044;border-radius:7px;overflow:hidden}.sensor-head,.sensor-row{display:grid;grid-template-columns:42% 25% 33%;align-items:center}.sensor-head{height:73px;color:#b3c7e6;font-size:14px;padding:0 78px;border-bottom:1px solid #163044}.sensor-row{height:45px;border-bottom:1px solid #163044;padding:0 74px;font-size:18px}.sensor-row span{display:flex;align-items:center;gap:20px}.sensor-row svg{width:19px;color:#00cef5;fill:none;stroke:currentColor;stroke-width:2}.sensor-row strong{color:#00baf2;font-weight:500}.sensor-row time{color:#a9c0de}.no-sensors{padding:18px;text-align:center;color:#9fb0c8}.count{color:#b3c3dd;margin:20px 14px}.modal{position:fixed;inset:0;background:#000a;display:grid;place-items:center;z-index:5}.modal form{width:min(430px,calc(100vw - 32px));padding:25px;background:#0a1827;border:1px solid #26516b;border-radius:9px}.modal h2{margin:0 0 20px}.modal label{display:grid;gap:6px;color:#b3c7e6;margin:12px 0}.modal input,.modal textarea{background:#07121f;border:1px solid #294b68;border-radius:5px;color:white;padding:9px;font:inherit}.modal textarea{min-height:70px}.modal footer{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}.modal footer button{padding:9px 17px;color:white;border:1px solid #294b68;border-radius:5px;background:#102133}.modal footer .primary{border:0}@media(max-width:850px){.objects-page{padding:18px 14px}.page-head{align-items:flex-start;gap:16px;flex-direction:column}.actions{gap:8px;width:100%;overflow:auto}.actions button{min-width:155px;height:44px;font-size:14px}.object-row{padding:0 10px;gap:10px}.object-toggle{min-width:0;gap:10px}.object-toggle svg{width:30px}.object-toggle b{font-size:16px}.sensor-actions{display:none}.sensor-head,.sensor-row{grid-template-columns:45% 27% 28%;padding:0 12px;font-size:12px}.sensor-head{padding:0 12px}.sensor-row span{gap:7px}.sensor-row time{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.object-row em{font-size:12px}.sensor-table{margin:10px 4px}}
</style>
